CREATE TABLE `aps_command_record` (
  `id` bigint NOT NULL,
  `idempotency_key` varchar(128) NOT NULL,
  `command_type` varchar(64) NOT NULL,
  `source_module` varchar(32) NOT NULL,
  `source_biz_no` varchar(64) NOT NULL,
  `source_biz_line_no` varchar(64) DEFAULT NULL,
  `result_id` bigint DEFAULT NULL,
  `creator` varchar(64) DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT NULL,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_aps_command_idempotency_deleted` (`idempotency_key`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='APS-跨模块命令幂等记录';
