CREATE TABLE `aps_projection_mat` (
  `id` bigint NOT NULL COMMENT '主键',
  `scenario_id` bigint NOT NULL COMMENT '排程场景编号',
  `source_mat_id` bigint NOT NULL COMMENT 'MDM物料编号',
  `mat_code` varchar(64) NOT NULL COMMENT '物料编码快照',
  `mat_name` varchar(128) NOT NULL COMMENT '物料名称快照',
  `mat_spec` varchar(255) DEFAULT NULL COMMENT '物料规格快照',
  `mat_type` varchar(32) NOT NULL COMMENT '物料类型快照',
  `base_uom_id` bigint NOT NULL COMMENT '基准计量单位编号',
  `base_uom_code` varchar(64) NOT NULL COMMENT '基准计量单位编码快照',
  `batch_flag` bit(1) NOT NULL COMMENT '是否批次管控',
  `bom_id` bigint NOT NULL DEFAULT '0' COMMENT '当前有效BOM编号，0表示无',
  `bom_version` varchar(32) DEFAULT NULL COMMENT '当前有效BOM版本',
  `route_id` bigint NOT NULL DEFAULT '0' COMMENT '当前有效工艺路线编号，0表示无',
  `route_version` varchar(32) DEFAULT NULL COMMENT '当前有效工艺路线版本',
  `source_update_time` datetime NOT NULL COMMENT '来源数据更新时间',
  `snapshot_time` datetime NOT NULL COMMENT '投影快照时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_aps_projection_mat_deleted` (`scenario_id`,`source_mat_id`,`deleted`),
  KEY `idx_aps_projection_mat_code` (`scenario_id`,`mat_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='APS-MDM物料投影';
